SELECT DISTINCT p.id, u.id
FROM users u
         CROSS JOIN polls p
WHERE u.email LIKE '%@autotest.com'
ON CONFLICT (poll_id, user_id) DO NOTHING;


SELECT id, 'poll_index_update', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'
FROM polls
WHERE id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM events_queue
    WHERE events_queue.entity_id = polls.id
      AND events_queue.event_name = 'poll_index_update'
);

